package com.combo.monkeycompanion.audio

import android.content.Context
import android.media.AudioAttributes
import android.media.AudioManager
import android.media.SoundPool
import com.combo.monkeycompanion.R
import com.combo.monkeycompanion.ai.ChatHub

/**
 * v10.8 tiny sound effects (Smash game + fireworks) on a SoundPool. WAVs are generated by tools/gen_sfx.py.
 * Plays on the media stream (so the system media volume applies), and stays quiet when:
 * Settings › Sound effects is off, the phone's ringer is on silent or vibrate, or the media volume is 0.
 * Lazily loaded on first use; [release] frees it.
 */
object Sfx {
    enum class S(val res: Int) {
        CRACK(R.raw.sfx_crack), SHATTER(R.raw.sfx_shatter), WHOOSH(R.raw.sfx_whoosh), MEGA(R.raw.sfx_mega),
        FW_BOOM(R.raw.sfx_fw_boom), FW_CRACKLE(R.raw.sfx_fw_crackle), WHISTLE(R.raw.sfx_whistle), FIZZ(R.raw.sfx_fizz),
        // v10.21 the Billa & Chittu show
        PLUCK(R.raw.sfx_pluck), ZIP(R.raw.sfx_zip), BOING(R.raw.sfx_boing), SPLAT(R.raw.sfx_splat), THUD(R.raw.sfx_thud),
        CLANG(R.raw.sfx_clang), BONK(R.raw.sfx_bonk), SLIDE(R.raw.sfx_slide), POP(R.raw.sfx_pop), WAHWAH(R.raw.sfx_wahwah), TADA(R.raw.sfx_tada),
    }

    /** v10.21 a show sound by its name in the episode script ("splat", "zip", …), or null. */
    fun byName(n: String?): S? = when (n) {
        "pluck" -> S.PLUCK; "zip" -> S.ZIP; "boing" -> S.BOING; "splat" -> S.SPLAT; "thud" -> S.THUD; "clang" -> S.CLANG
        "bonk" -> S.BONK; "slide" -> S.SLIDE; "pop" -> S.POP; "wahwah" -> S.WAHWAH; "tada" -> S.TADA; else -> null
    }
    private var pool: SoundPool? = null
    private val ids = IntArray(S.values().size)
    private val ready = BooleanArray(S.values().size)
    private var app: Context? = null
    private var lastAt = LongArray(S.values().size)

    private fun ensure(c: Context): SoundPool? {
        pool?.let { return it }
        val ctx = c.applicationContext; app = ctx
        val sp = runCatching {
            SoundPool.Builder().setMaxStreams(8).setAudioAttributes(
                AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_GAME).setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION).build()
            ).build()
        }.getOrNull() ?: return null
        sp.setOnLoadCompleteListener { _, id, status -> val i = ids.indexOf(id); if (i >= 0 && status == 0) ready[i] = true }
        for (s in S.values()) ids[s.ordinal] = runCatching { sp.load(ctx, s.res, 1) }.getOrDefault(0)
        pool = sp
        return sp
    }

    /** May we make a sound right now? */
    fun allowed(c: Context): Boolean {
        if (!runCatching { ChatHub.settings.soundEffects }.getOrDefault(true)) return false
        val am = c.getSystemService(AudioManager::class.java) ?: return false
        if (am.ringerMode != AudioManager.RINGER_MODE_NORMAL) return false
        return am.getStreamVolume(AudioManager.STREAM_MUSIC) > 0
    }

    /** Loads the sounds ahead of time (so the first crack isn't silent). */
    fun warm(c: Context) { if (allowed(c)) ensure(c) }

    /** [pitch] 0.5..2 (SoundPool rate), [vol] 0..1. Rate-limited per sound (35 ms) so bursts don't pile up. */
    fun play(c: Context, s: S, vol: Float = 1f, pitch: Float = 1f) {
        if (!allowed(c)) return
        val sp = ensure(c) ?: return
        val i = s.ordinal
        if (!ready[i]) return
        val now = android.os.SystemClock.uptimeMillis()
        if (now - lastAt[i] < 35L && s != S.PLUCK) return
        lastAt[i] = now
        val v = vol.coerceIn(0f, 1f)
        runCatching { sp.play(ids[i], v, v, 1, 0, pitch.coerceIn(0.5f, 2f)) }
    }

    fun release() {
        runCatching { pool?.release() }; pool = null
        ready.fill(false); ids.fill(0)
    }
}
